package tv.metaxy.proof;
import android.content.*;import android.net.Uri;import android.os.*;import android.util.Base64;
import com.cgutman.adblib.*;import java.io.*;import java.nio.channels.*;import java.security.*;import java.util.concurrent.*;
/** An opt-in local ADB bootstrap. The app's own key never leaves private storage. */
final class LocalAdbBootstrap {
 interface Listener{void status(String message);void done(boolean ok,String message);}
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();private static final Handler main=new Handler(Looper.getMainLooper());private static volatile boolean busy;private static volatile String phase="Not connected locally";private static volatile LocalAdbSession active;
 /** Check before every new layout; a live helper alone is not an ADB recovery route. */
 static void checkRecovery(Listener listener){worker.execute(()->{boolean ok=false;try(java.net.Socket probe=new java.net.Socket()){probe.connect(new java.net.InetSocketAddress("127.0.0.1",5555),1200);ok=true;}catch(IOException ignored){}final boolean ready=ok;main.post(()->listener.done(ready,ready?"Network debugging is listening on this Shield":"Network debugging is not reachable on port 5555. Enable it in Developer options before starting a two-app layout. Keep a trusted computer authorized for recovery."));});}
 static boolean enabled(Context c){return c.getSharedPreferences("local-adb",0).getBoolean("enabled",false);}
 static String phase(){return phase;}
 static void cancel(){LocalAdbSession s=active;if(s!=null)try{s.close();}catch(IOException ignored){}}
 static IBinder broker(Context c){IBinder b=WindowBrokerProvider.current();if(b!=null)return b;try{Bundle result=c.getContentResolver().call(Uri.parse("content://tv.metaxy.proof.windowbroker"),"owner_broker",null,null);return result==null?null:result.getBinder("broker");}catch(Exception e){return null;}}
 private static void update(Listener l,String text){phase=text;main.post(()->l.status(text));}
 static void connect(Context context,Listener listener){final Context c=context.getApplicationContext();synchronized(LocalAdbBootstrap.class){if(busy){listener.done(false,"A local connection is already in progress");return;}busy=true;}worker.execute(()->{boolean ok=false;String result;try{IBinder present=broker(c);if(present!=null&&present.pingBinder()){ok=true;result="Window support is connected";}else{
   update(listener,"Preparing this app's private debugging key…");File dir=new File(c.getNoBackupFilesDir(),"local-adb");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Cannot create private key storage");AdbCrypto key;
   try(RandomAccessFile lock=new RandomAccessFile(new File(dir,"key.lock"),"rw");FileLock held=lock.getChannel().lock()){File priv=new File(dir,"private.pk8"),pub=new File(dir,"public.der");AdbBase64 encode=data->Base64.encodeToString(data,Base64.NO_WRAP);if(priv.exists()&&pub.exists())key=AdbCrypto.loadAdbKeyPair(encode,priv,pub);else{key=AdbCrypto.generateAdbKeyPair(encode);key.saveAdbKeyPair(priv,pub);}priv.setReadable(false,false);priv.setWritable(false,false);priv.setReadable(true,true);priv.setWritable(true,true);pub.setReadable(false,false);pub.setReadable(true,true);}
   update(listener,"Connecting to this Shield. If Android asks, approve Kinegra Home and select Always allow.");try(LocalAdbSession session=new LocalAdbSession(5555)){active=session;session.authenticate(key);if(!"2000".equals(session.shell("id -u")))throw new IOException("Local ADB did not provide the expected shell identity");
    update(listener,"Installing the bundled window helper…");byte[] jar=asset(c,"window-broker.jar",4*1024*1024);String expected=new String(asset(c,"window-broker.sha256",128),"UTF-8").trim();if(!expected.matches("[0-9a-f]{64}")||!digest(jar).equals(expected))throw new IOException("Bundled helper verification failed");int uid=android.os.Process.myUid();String path="/data/local/tmp/kinegra-home-"+uid+"-broker.jar";session.push(jar,path+".incoming");String uploaded=session.shell("sha256sum "+path+".incoming");if(!uploaded.startsWith(expected+" "))throw new IOException("Uploaded helper verification failed");
    update(listener,"Starting local window support…");String command="set -e; mv "+path+".incoming "+path+" && chmod 600 "+path+"; for p in $(pidof KinegrarchyWindowBroker 2>/dev/null); do case $p in *[!0-9]*|'') continue;; esac; if grep -q '^Uid:[[:space:]]*2000[[:space:]]' /proc/$p/status && tr '\\000' ' ' </proc/$p/cmdline | grep -q KinegrarchyWindowBroker; then kill $p; fi; done; CLASSPATH="+path+" setsid nohup app_process /system/bin --nice-name=KinegrarchyWindowBroker KinegrarchyWindowBroker "+uid+" >/data/local/tmp/kinegra-home-"+uid+".log 2>&1 </dev/null & sleep 1; echo KINEGRA_HELPER_LAUNCHED";String launched=session.shell(command);if(!launched.endsWith("KINEGRA_HELPER_LAUNCHED"))throw new IOException("Local helper launch did not complete: "+launched);
    for(int n=0;n<30;n++){IBinder b=broker(c);if(b!=null&&b.pingBinder()){ok=true;break;}Thread.sleep(200);}if(!ok)throw new IOException("The local helper did not attach. Check Diagnostics.");
   }
   c.getSharedPreferences("local-adb",0).edit().putBoolean("enabled",true).putInt("last_boot",android.provider.Settings.Global.getInt(c.getContentResolver(),"boot_count",-1)).apply();result="Window support connected locally";
  }}catch(java.net.ConnectException e){result="Enable Network debugging in the Shield's Developer options, then try Connect locally.";}catch(java.net.SocketTimeoutException e){result="Android debugging approval timed out. Choose Always allow for Kinegra Home when Android asks, then retry.";}catch(Exception e){result="Local connection failed: "+e.getClass().getSimpleName()+". "+(e.getMessage()==null?"Retry local setup.":e.getMessage());}finally{active=null;busy=false;}phase=result;final boolean success=ok;final String message=result;main.post(()->listener.done(success,message));});}
 private static byte[] asset(Context c,String name,int max)throws IOException{try(InputStream in=c.getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Asset too large");out.write(b,0,n);}return out.toByteArray();}}
 private static String digest(byte[] b)throws NoSuchAlgorithmException{StringBuilder s=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(java.util.Locale.ROOT,"%02x",n&255));return s.toString();}
}
